var i=`0354-schwarzwalder-kirschtorte`;var r=`world-0354`;var o=`DE`;var a=`western-europe`;var n=8;var l=149;var s={en:`Schwarzwälder Kirschtorte`,ua:`Торт «Чорний ліс»`};var h={en:`A traditional Germany dish made with all-purpose flour, chicken egg, whole cow milk, baking powder. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, розпушувач тіста. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var c=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:12,i:[[`all-purpose-flour`,240,`g`],[`chicken-egg`,5,`pcs`],[`white-granulated-sugar`,210,`g`],[`cocoa-powder`,65,`g`],[`unsalted-butter`,100,`g`],[`whole-cow-milk`,210,`ml`],[`baking-powder`,9,`g`]]},{en:`Bake in a preheated 180°C oven for about 33 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 33 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:33,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:9,i:[[`heavy-cream`,700,`ml`],[`powdered-sugar`,105,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Layer the cooled cocoa cake with whipped cream and pitted sour cherries, brushing each layer with the cherry cooking liquid; coat with chocolate shavings.`,ua:`Перешаруйте охолоджений шоколадний бісквіт збитими вершками та вишнями без кісточок, зволожуючи коржі вишневим сиропом; обсипте шоколадною стружкою.`,t:[`layered-assembly`],m:15,i:[[`sour-cherry`,400,`g`],[`water`,150,`ml`],[`dark-chocolate`,130,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 80 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 80 хвилин.`,t:[`rapid-chilling`],m:80,i:[]}];var d={slug:i,id:r,country:`DE`,region:a,servings:8,minutes:149,title:s,text:h,steps:c};export{o as country,d as default,r as id,l as minutes,a as region,n as servings,i as slug,c as steps,h as text,s as title};